  EntryOrigin,
  ExecutionService,
  ExecutionItem,
  MovementDraft,
  MovementOrder,
  MovementReason,
  RequestedMovement,
} from './types';

export const REASON_LABELS: Readonly<Record<MovementReason, string>> = {
  repair: 'PARA REPARACIÓN',
  retention: 'PARA RETÉN',
  claim: 'PARA RECLAMO',
  rotation: 'ROTACIÓN',
  discard: 'PARA SCRAP',
  retread: 'REENCAUCHE',
  balancing: 'BALANCEO',
};

const DEFAULT_LOGIN_DOMAIN = 'operarios.renova.local';

function configuredLoginDomains(): string[] {
  const raw = import.meta.env.VITE_SUPABASE_LOGIN_EMAIL_DOMAINS as string | undefined;
  const parsed = raw
    ?.split(',')
    .map((value) => value.trim().toLowerCase().replace(/^@+/, ''))
    .filter(Boolean);
  return parsed?.length ? [...new Set(parsed)] : [DEFAULT_LOGIN_DOMAIN];
}

